/* @author MILO-GAO(高振銘)@2020 */ package page2020.anno;import java.lang.reflect.Field;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import page2020.core.App;import page2020.core.Log;import page2020.util.EmptyUtil;public class TableProp extends DataProp<TableProp, ColItem> {	private static Logger log = LoggerFactory.getLogger(TableProp.class);	private Table2020 anno = null;	private Data2020 data2020 = null;	public TableProp(Class<?> clazz, String alias) {		super(clazz);		Table2020 anno = null;		String topClassName = null;		if (clazz.isAnnotationPresent(Table2020.class)) {			anno = clazz.getAnnotation(Table2020.class);			topClassName = EmptyUtil.not(alias) ? alias : anno.name();			super.base(topClassName);			this.anno = anno;			if (Log.anno) {				log.info(this.toString());			}		} else {			log.error("TableProp: '" + clazz.getCanonicalName() + "' is NOT Table2020 annotation !");			return;		}		Class<?> superClazz = clazz;		do {			String annoClassName = null;			if (superClazz.isAnnotationPresent(Table2020.class)) {				annoClassName = superClazz.getAnnotation(Table2020.class).name();			}			if (EmptyUtil.is(annoClassName)) {				annoClassName = App.className(superClazz);			}					Field[] fields = superClazz.getDeclaredFields();			for (int i=0; i < fields.length; i++) {				super.cache(new ColItem(fields[i], annoClassName, topClassName));			}			super.storage();			superClazz = superClazz.getSuperclass();		} while (! superClazz.equals(Object.class));		super.sorting();		if (clazz.isAnnotationPresent(Data2020.class)) {			this.data2020 = clazz.getAnnotation(Data2020.class);			}		if (Log.anno) {			log.info(this.toString());			int count = super.count();			for (int i=0; i < count; i++) {				log.info("[" + i + "] " + super.value(i).toString());			}		}	}	public ColItem itemByField(String fieldName) {		int size = super.count();		for (int i=0; i < size; i++) {			if (super.value(i).getFieldName().equals(fieldName)) {				return super.value(i);			}		}		return null;	}	@Override	public String toString() {		return "TableProp [getDataKeys()=" + getDataKeys() + ", getDisplayNames()=" + getDisplayNames() + "]";	}	public Table2020 getAnno() {		return anno;	}	public void setAnno(Table2020 anno) {		this.anno = anno;	}	public Data2020 getData2020() {		return data2020;	}	public void setData2020(Data2020 data2020) {		this.data2020 = data2020;	}}